// Unfinished native boundaries plus optional repair history in an unused CAD
// block. No executable or sidecar is needed to recover the editable draft.
using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Web.Script.Serialization;
using O=System.Collections.Generic.Dictionary<string,object>;
namespace SketchRust.Compat {
 public sealed partial class ApexFile {
  const string DraftBlock="__SKETCH_RUST_DRAFTS_V1";
  static readonly JavaScriptSerializer ModelJson=new JavaScriptSerializer{MaxJsonLength=Limit};
  void AddDrafts(O modelPage,NativePage page,O model,ref int key){
   var drafts=Items(modelPage,"reopenedAreas").ToArray();var faces=Items(modelPage,"polygons").Where(p=>Get(p,"apexBoundary")!=null&&ModelJson.Serialize(Items(p,"points").ToArray())!=ModelJson.Serialize(Items(Map(Get(p,"apexBoundary")),"points").ToArray())).Select(p=>Obj("original",p,"boundary",Get(p,"apexBoundary"))).ToArray();if(drafts.Length==0&&faces.Length==0)return;var lines=Items(modelPage,"lines").ToDictionary(l=>(int)Num(l,"id"));
   foreach(var draft in drafts){var poly=Map(Get(draft,"original"));int areaId=(int)Num(poly,"id");if(page.Areas.Any(a=>a.Key==areaId-1))continue;var points=Items(poly,"points").ToArray();var edges=Items(poly,"edges").ToArray();
    var boundary=Entity(13,key++,Version,0,0);boundary.Flags=16384;
    // The real open native boundary follows one continuous surviving run.
    // Other surviving segments already exist as free native lines.
    var run=new List<int>();var best=new List<int>();for(int i=0;i<edges.Length*2;i++){int at=i%edges.Length,lineId=(int)Num(edges[at],"lineId");if(lines.ContainsKey(lineId)&&run.Count<edges.Length){run.Add(at);if(run.Count>best.Count)best=run.ToList();}else run.Clear();}
    foreach(int i in best){int lineId=(int)Num(edges[i],"lineId");var line=lines[lineId];var start=Map(Get(line,"start"));double bow=Num(line,"bowAngle");if(i<points.Length&&(Math.Abs(Num(start,"x")-Num(points[i],"x"))>1e-7||Math.Abs(Num(start,"y")-Num(points[i],"y"))>1e-7))bow=-bow;boundary.Children.Add(Entity(14,lineId-1,Version,Num(points[i],"x"),Num(points[i],"y"),0,0,0,Math.Tan(-bow*Math.PI/720)));}
    if(best.Count>0){int end=(best.Last()+1)%points.Length;boundary.Children.Add(Entity(14,key++,Version,Num(points[end],"x"),Num(points[end],"y"),0,0,0,0));}
    else foreach(var point in points.Take(1))boundary.Children.Add(Entity(14,key++,Version,Num(point,"x"),Num(point,"y"),0,0,0,0));
    var consumed=new HashSet<int>(best.Select(i=>(int)Num(edges[i],"lineId")-1));page.Entities.RemoveAll(e=>(e.Type==2||e.Type==4)&&consumed.Contains(e.Key));
    var tags=Map(Get(poly,"attributes"));var area=new NativeArea{Key=areaId-1,SecondKey=areaId-1,Closed=0,Entity=page.Entities.Count,Name=Str(poly,"name"),Code=Str(poly,"type","UND"),Description=Str(tags,"apex.description"),Height=Num(tags,"apex.averageWallHeight")};double factor=Num(poly,"factorOverride",1);area.Factor=Math.Abs(factor);area.Sign=(byte)(factor<0?0:1);area.Attributes=StoreTags(area.Attributes,tags,Version);page.Entities.Add(boundary);page.Areas.Add(area);
   }
   string encoded=Convert.ToBase64String(Encoding.UTF8.GetBytes(ModelJson.Serialize(Obj("version",1,"drafts",drafts,"liveLines",Items(modelPage,"lines").ToArray(),"faces",faces,"layers",Get(model,"layers"),"activeLayerId",Get(model,"activeLayerId"),"settings",Obj("options",Get(Map(Get(model,"settings")),"options",new O()))))));var block=new Block{Name=DraftBlock,Tail=new byte[Version>=38?21:Version>=32?4:0]};for(int offset=0;offset<encoded.Length;offset+=60000){var text=Entity(7,key++,Version,0,0,1);text.Text=encoded.Substring(offset,Math.Min(60000,encoded.Length-offset));text.Extras=new byte[Version>=38?27:24];if(Version>=38)text.Extras[25]=1;block.Entities.Add(text);}page.Blocks.Add(block);
  }
  O ReadState(NativePage page){var block=page.Blocks.FirstOrDefault(b=>b.Name==DraftBlock);if(block==null)return new O();string encoded=String.Concat(block.Entities.Where(e=>e.Type==7).Select(e=>e.Text));if(encoded.Length>Limit)throw new InvalidDataException("Native repair history exceeds the size limit");var payload=ModelJson.Deserialize<O>(Encoding.UTF8.GetString(Convert.FromBase64String(encoded)));if(Num(payload,"version")!=1)throw new InvalidDataException("Unsupported native draft history");return payload;}
  List<O> ReadDrafts(NativePage page){return Items(ReadState(page),"drafts").Where(d=>page.Areas.Any(a=>a.Closed==0&&(a.Key==(int)Num(Map(Get(d,"original")),"id")-1||(Version<23&&a.Name==Str(Map(Get(d,"original")),"name")&&a.Code==Str(Map(Get(d,"original")),"type"))))).ToList();}
  static bool SameLine(O a,O b){var s=Map(Get(a,"start"));var e=Map(Get(a,"end"));var x=Map(Get(b,"start"));var y=Map(Get(b,"end"));Func<O,O,bool> near=(p,q)=>Math.Abs(Num(p,"x")-Num(q,"x"))<1e-7&&Math.Abs(Num(p,"y")-Num(q,"y"))<1e-7;return (near(s,x)&&near(e,y)&&Math.Abs(Num(a,"bowAngle")-Num(b,"bowAngle"))<1e-7)||(near(s,y)&&near(e,x)&&Math.Abs(Num(a,"bowAngle")+Num(b,"bowAngle"))<1e-7);}
  void RestoreDraftLines(NativePage page,List<O> polygons,List<O> lines,ref int next){var state=ReadState(page);var original=Items(state,"liveLines").ToList();if(original.Count==0||(!Items(state,"drafts").Any()&&!Items(state,"faces").Any())||!original.All(l=>lines.Any(n=>SameLine(l,n)))||!lines.All(l=>original.Any(n=>SameLine(l,n))))return;var map=new Dictionary<int,int>();foreach(var line in lines)map[(int)Num(line,"id")]=(int)Num(original.First(l=>SameLine(l,line)),"id");var ids=new HashSet<int>(original.Select(l=>(int)Num(l,"id")).Concat(Items(state,"drafts").Select(d=>(int)Num(Map(Get(d,"original")),"id"))));foreach(var poly in polygons){if(ids.Contains((int)Num(poly,"id")))poly["id"]=next++;foreach(var edge in Items(poly,"edges")){if(Object.Equals(Get(poly,"apexRestoredFace"),true))continue;int value;if(map.TryGetValue((int)Num(edge,"lineId"),out value))edge["lineId"]=value;}}lines.Clear();lines.AddRange(original);importedLayers=Get(state,"layers");importedActiveLayer=Get(state,"activeLayerId");}
  O importedOptions;object importedLayers,importedActiveLayer;
  O RestoreOptions(O settings){if(importedOptions!=null)settings["options"]=importedOptions;return settings;}
  void RestoreFaces(NativePage page,List<O> polygons,List<O> lines,ref int next){var state=ReadState(page);foreach(var face in Items(state,"faces")){var original=Map(Get(face,"original"));int index=polygons.FindIndex(p=>Num(p,"id")==Num(original,"id"));if(index<0)continue;var actual=Items(polygons[index],"points").ToArray();var expected=Items(Map(Get(face,"boundary")),"points").ToArray();if(actual.Length!=expected.Length||actual.Where((p,i)=>Math.Abs(Num(p,"x")-Num(expected[i],"x"))>1e-7||Math.Abs(Num(p,"y")-Num(expected[i],"y"))>1e-7).Any())continue;var ids=new HashSet<int>(Items(polygons[index],"edges").Select(e=>(int)Num(e,"lineId")));lines.RemoveAll(l=>ids.Contains((int)Num(l,"id")));original["name"]=Get(polygons[index],"name");original["type"]=Get(polygons[index],"type");original["factorOverride"]=Get(polygons[index],"factorOverride");original["subtractMode"]=Get(polygons[index],"subtractMode");original["subtractTargetId"]=Get(polygons[index],"subtractTargetId");var attributes=Map(Get(original,"attributes"));attributes["apex.calculation"]="net";original["attributes"]=attributes;original["apexRestoredFace"]=true;polygons[index]=original;importedLayers=Get(state,"layers");importedActiveLayer=Get(state,"activeLayerId");importedOptions=Map(Get(Map(Get(state,"settings")),"options"));next=Math.Max(next,(int)Num(original,"id")+1);}}
 }
}
